style.css:
@-moz-document domain("youtube.com") {
ytd-app {
    background: transparent !important;
  }

  ytd-app::before {
    content: "" !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    background: linear-gradient(to bottom, #ffffff 0%, #ffb3cc 100%) !important;
    z-index: -2 !important;
    pointer-events: none !important;
  }

  ytd-app::after {
    content: "" !important;
    position: fixed !important;
    top: -50% !important;
    left: -50% !important;
    width: 200% !important;
    height: 200% !important;
    background-image: radial-gradient(circle, #ffb3cc 5px, transparent 5px) !important;
    background-size: 26px 26px !important;
    transform: rotate(30deg) !important;
    z-index: -1 !important;
    pointer-events: none !important;
  }

  #masthead {
    background-color: #ffa3bf !important;
    border-bottom: none !important;
  }

  #guide-inner-content,
  tp-yt-app-drawer,
  ytd-guide-renderer {
    background-color: #f9dbe5 !important;
  }

  ytd-guide-entry-renderer:hover {
    background-color: #ffb3cc !important;
    border-radius: 8px !important;
  }

  ytd-guide-entry-renderer[active] {
    background-color: #ff80c8 !important;
    border-radius: 8px !important;
  }

  ytd-guide-entry-renderer[active] yt-formatted-string {
    color: #ffffff !important;
  }

  yt-chip-cloud-chip-renderer {
    background-color: rgba(255, 255, 255, 0.9) !important;
    border: 1px solid #f48fb1 !important;
    color: #ad1457 !important;
    border-radius: 20px !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: #ff80c8 !important;
    color: #ffffff !important;
    border-color: #ff80c8 !important;
  }

  #subscribe-button yt-button-shape button {
    background-color: #ff80c8 !important;
    color: #ffffff !important;
    border-radius: 20px !important;
  }

  .ytp-play-progress,
  .ytp-swatch-background-color {
    background-color: #ff80c8 !important;
  }
}
